function Announcement(){
 const [a,setA]=useState(null);
 useEffect(()=>{bm.state().then(s=>setA(s.announcement||null));return bm.subscribe(e=>{if(e.type==='state')setA(e.state.announcement||null);});},[]);
 useEffect(()=>{document.body.classList.toggle('has-ann',!!a);},[a]);
 if(!a)return null;
 return <div className="announcement" role="status"><span>📢 {a.message}</span><button aria-label="Close announcement" onClick={()=>bm.closeAnnouncement(a.id).then(s=>setA(s.announcement||null))}>✕</button></div>;
}
function MajorAnnouncements(){
 const [st,setSt]=useState({major:[],majorSeen:[]});const [open,setOpen]=useState(false);const [item,setItem]=useState(null);
 useEffect(()=>{bm.state().then(s=>setSt(s));return bm.subscribe(e=>{if(e.type==='state')setSt(e.state);});},[]);
 const list=st.major||[],seen=new Set(st.majorSeen||[]);const unread=list.filter(i=>!seen.has(i.id)).length;
 if(st.locked||!st.linked||!st.signedIn)return null;
 const view=i=>{setItem(i);if(!seen.has(i.id))bm.majorSeen(i.id).then(setSt);};
 const when=d=>{const t=new Date(d);return isNaN(t)?'':t.toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});};
 return <>
  <button className={'major-icon'+(unread?' has-new':'')} aria-label={unread?unread+' new announcements':'Announcements'} onClick={()=>{setItem(null);setOpen(true);}}>📣{unread>0&&<span className="major-count">{unread}</span>}</button>
  {open&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setOpen(false);}}><div className="modal major-modal">
   {item?<><h2>{item.title}</h2><p className="major-date">{when(item.created_at)}</p><div className="major-body">{item.body}</div><div className="modal-actions"><button className="primary" autoFocus onClick={()=>setItem(null)}>Back to list</button><button onClick={()=>setOpen(false)}>Close</button></div></>
   :<><h2>Announcements</h2>{list.length===0?<p>There are no announcements right now.</p>:<ul className="major-list">{list.map((i,n)=><li key={i.id}><button autoFocus={n===0} onClick={()=>view(i)}>{!seen.has(i.id)&&<span className="major-dot"/>}<strong>{i.title}</strong><small>{when(i.created_at)}</small></button></li>)}</ul>}<div className="modal-actions"><button onClick={()=>setOpen(false)}>Close</button></div></>}
  </div></div>}
 </>;
}
createRoot(document.getElementById('root')).render(<><App/><Announcement/><MajorAnnouncements/></>);
const heroCache=new Map();
/** Films/Series top panel (matches Android): backdrop, title, rating · year · length · genre, cast, director, plot. */
function SeriesPage({series,ratingLabel,bar,back,actions,onPlay}){
 const item=series.item,[info,setInfo]=useState(null),[pos,setPos]=useState({}),top=useRef(null),scroll=useRef(null);
 useEffect(()=>{const key=item.kind+':'+item.id;if(heroCache.has(key)){setInfo(heroCache.get(key));return;}bm.details({kind:item.kind,id:item.id}).then(r=>{heroCache.set(key,r);setInfo(r);}).catch(()=>{});},[item.id]);
 useLayoutEffect(()=>{top.current?.focus({preventScroll:true});if(scroll.current)scroll.current.scrollTop=0;},[item.id]);
 const seasons=Object.keys(series.episodes).sort((a,b)=>Number(a)-Number(b));
 const meta=[info?.rating&&info.rating!=='0'?'★ '+info.rating:'',info?.year,seasons.length+(seasons.length===1?' season':' seasons'),info?.genre].filter(Boolean).join('  •  ');
 return <main className="series-page">{(info?.backdrop||series.info.cover||item.poster)&&<img className="series-backdrop" src={info?.backdrop||series.info.cover||item.poster} alt=""/>}<div className="series-shade"/><div ref={scroll} className="series-scroll"><button ref={top} className="series-back" onClick={back}>← Series</button><div className="series-info"><h1>{item.name}</h1><p>{meta}</p><p className="muted">{ratingLabel(item)}</p>{info?.cast&&<p className="one-line"><span className="muted">Cast:</span> {info.cast}</p>}<p className="series-plot">{info?.plot||series.info.plot}</p>{actions}</div>{seasons.map(s=>{const eps=series.episodes[s]||[];return <section className="season-row" key={s}><div className="season-head"><h2>Season {s}</h2><span>{(pos[s]||0)+1} / {eps.length}</span></div><div className="episode-strip">{eps.map((ep,i)=>{const {number,title}=episodeTitle(ep,item.name);return <button key={ep.id} className="episode-card" onFocus={e=>{setPos(p=>({...p,[s]:i}));e.currentTarget.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});}} onClick={()=>onPlay(ep)}>{ep.poster||item.poster?<img src={ep.poster||item.poster} alt="" loading="lazy"/>:<div className="no-poster">🎬</div>}<div className="ep-name">{number&&<span className="ep-no">Episode {number}</span>}{title&&<span className="ep-title">{title}</span>}</div>{bar(ep)}</button>;})}</div></section>;})}</div></main>;
}
function MediaHero({item,ratingLabel}){
 const [info,setInfo]=useState(null);
 useEffect(()=>{setInfo(null);if(!item||!['film','series'].includes(item.kind))return;const key=item.kind+':'+item.id;if(heroCache.has(key)){setInfo(heroCache.get(key));return;}let live=true;const t=setTimeout(()=>{bm.details({kind:item.kind,id:item.id}).then(r=>{heroCache.set(key,r);if(live)setInfo(r);}).catch(()=>{});},300);return()=>{live=false;clearTimeout(t);};},[item?.kind,item?.id]);
 if(!item)return <div className="media-hero"/>;
 const dur=String(info?.duration||'').replace(/^0?(\d+):(\d+):\d+$/,'$1h $2m');
 const meta=[info?.rating&&info.rating!=='0'?'★ '+info.rating:'',info?.year,dur&&!dur.startsWith('00:00')?dur:'',info?.genre].filter(Boolean).join('  ·  ');
 return <div className="media-hero">{(info?.backdrop||item.poster)&&<img className="media-backdrop" src={info?.backdrop||item.poster} alt=""/>}<div className="media-info"><h1>{item.name}</h1><p className="muted">{meta}{meta?'  ·  ':''}{ratingLabel(item)}</p>{info?.cast&&<p><span className="muted">Cast:</span> {info.cast}</p>}{info?.director&&<p><span className="muted">Director:</span> {info.director}</p>}{info?.plot&&<p className="media-plot">{info.plot}</p>}</div></div>;
}

/** First open: the customer chooses their 4-digit BM Player PIN (typed twice). */
function PinSetup({state,setState}){const[pin,setPin]=React.useState('');const[again,setAgain]=React.useState('');const[err,setErr]=React.useState('');const[busy,setBusy]=React.useState(false);const d=v=>v.replace(/\D/g,'').slice(0,4);
 return <main className="link-screen"><img src="logo.png" alt="BM Support" width="90"/><h1>Choose a PIN</h1><p className="muted">Pick a 4-digit PIN. BM Player will ask for it each time it opens. It shows in your subscription box on bmsupport.uk.</p><form className="modal-actions" onSubmit={async e=>{e.preventDefault();if(busy)return;if(pin!==again){setErr("The PINs didn't match. Try again.");setAgain('');return;}setBusy(true);setErr('');try{setState(await bm.pinCreate(pin));}catch(error){setErr(safeText(error.message,"Couldn't save your PIN. Try again."));setPin('');setAgain('');}finally{setBusy(false);}}}><input aria-label="New PIN" autoFocus type="password" inputMode="numeric" autoComplete="off" maxLength={4} placeholder="New PIN" value={pin} onChange={e=>setPin(d(e.target.value))}/><input aria-label="Repeat PIN" type="password" inputMode="numeric" autoComplete="off" maxLength={4} placeholder="Repeat PIN" value={again} onChange={e=>setAgain(d(e.target.value))}/>{err&&<p role="alert">{err}</p>}<button className="primary" type="submit" disabled={busy||pin.length!==4||again.length!==4}>{busy?'Saving…':'Save PIN'}</button><button type="button" onClick={()=>bm.exit()}>Close app</button></form><span className="version">v{state.version} · {state.platformName||'Windows'}</span></main>;}


/** First-visit 2FA setup: authenticator QR, store-download QR pop-ups for iPhone/Android, then one 6-digit code. */
function TotpSetup({data,version,platformName,onDone}){
 const [code,setCode]=React.useState('');const [err,setErr]=React.useState('');const [busy,setBusy]=React.useState(false);const [store,setStore]=React.useState(null);
 const svg=v=>typeof v==='string'&&v.trim().startsWith('<svg')?{__html:v}:null;
 return <main className="link-screen"><img src="logo.png" alt="BM Support" width="90"/><h1>Set up 2FA</h1>
  <p className="muted">1. Scan this QR code with an authenticator app on your phone. 2. Type the 6-digit code it shows. BM Player will ask for a code once a day.</p>
  {svg(data.qr_svg)&&<div className="qr-box" style={{background:'#fff',padding:8,borderRadius:8,width:220}} dangerouslySetInnerHTML={svg(data.qr_svg)}/>}
  <p className="muted">Or type this key: <code>{data.secret}</code></p>
  <p>No authenticator app? Get one:</p>
  <div className="modal-actions"><button type="button" onClick={()=>setStore('apple')}>iPhone (App Store)</button><button type="button" onClick={()=>setStore('android')}>Android (Play Store)</button></div>
  <form className="modal-actions" onSubmit={async e=>{e.preventDefault();if(busy)return;setBusy(true);setErr('');try{onDone(await bm.totpConfirm(code));}catch(error){setErr(safeText(error.message,"Couldn't check. Check the internet and try again."));setCode('');}finally{setBusy(false);}}}>
   <input aria-label="Authenticator code" autoFocus inputMode="numeric" autoComplete="off" maxLength={6} value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,''))}/>
   {err&&<p role="alert">{err}</p>}
   <button className="primary" type="submit" disabled={busy||code.length!==6}>{busy?'Checking…':'Turn on 2FA'}</button>
  </form>
  {store&&<div className="modal-backdrop" role="dialog" aria-label="Download authenticator"><div className="modal"><h2>Google Authenticator for {store==='apple'?'iPhone':'Android'}</h2><p className="muted">Scan with your phone's camera to download it.</p>
   {svg(store==='apple'?data.apple_qr_svg:data.android_qr_svg)&&<div style={{background:'#fff',padding:8,borderRadius:8,width:240}} dangerouslySetInnerHTML={svg(store==='apple'?data.apple_qr_svg:data.android_qr_svg)}/>}
   <div className="modal-actions"><button className="primary" type="button" onClick={()=>setStore(null)}>Close</button></div></div></div>}
  <span className="version">v{version} · {platformName||'Windows'}</span></main>;
}
/** Display the device code for entry on the website; polling delivers its login. */
function SigninScreen({bm,platformName,code}){
  const [msg,setMsg]=React.useState('');
  const [busy,setBusy]=React.useState(false);
  const refresh=async()=>{setBusy(true);setMsg('');try{await bm.link();}catch(e){setMsg(safeText(e?.message,"Couldn't get a code. Check the internet and try again."));}finally{setBusy(false);}};
  React.useEffect(()=>{if(!code)void refresh();},[]);
  return <main className="family-screen"><section className="family-panel compact">
    <h1>Welcome to BM Player</h1>
    <p className="muted">Sign in at bmsupport.uk, switch to the profile you want, then open Link Device. Enter the 6-digit linking code shown below and press Link this device.</p>
    <div className="code-boxes" aria-label="Device linking code">{Array.from({length:6},(_,i)=><span key={i}>{code?.[i]||'—'}</span>)}</div>
    <p className="status-line">{msg||'Waiting for you to link this device…'}</p>
    <button disabled={busy} onClick={refresh}>{busy?'Getting your code…':'New code'}</button>
    <p className="muted">No website account? Create one at bmsupport.uk/signup</p>
    <span className="version">{platformName}</span>
  </section></main>;
}
